def register(key,title,url,file=None,scope='',note='',state='inspected'):
 data={'id':key,'title':title,'url':url,'scope_actually_inspected':scope,'note':note,'state':state}
 if file:
  p=W/'sources'/file
  data['artifact']=str(p);data['sha256']=hashlib.sha256(p.read_bytes()).hexdigest()
 catalog[key]=data

